<script setup lang="ts">import {computed,ref} from "vue";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Budgets & Forecasts","Budget, actual and clearly labelled forecast comparison.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.budgets(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),department=ref("All departments"),year=ref("FY 2026");const rows=computed(()=>(s.data.value??[]).filter(x=>department.value==='All departments'||x.department===department.value).map(x=>({...x,variance:x.budget-x.actual,status:x.actual>x.budget?'over_budget':'on_track'}))),budget=computed(()=>rows.value.reduce((a,x)=>a+x.budget,0)),actual=computed(()=>rows.value.reduce((a,x)=>a+x.actual,0)),forecast=computed(()=>rows.value.reduce((a,x)=>a+x.forecast,0));const columns:Column[]=[{key:"account",header:"Account"},{key:"department",header:"Department"},{key:"category",header:"Category"},{key:"month",header:"Month"},{key:"budget",header:"Budget",align:"right",class:"num"},{key:"actual",header:"Actual",align:"right",class:"num"},{key:"variance",header:"Variance",align:"right",class:"num"},{key:"forecast",header:"AI forecast",align:"right",class:"num"},{key:"status",header:"Status"}];</script><template><AppShell><PageHeader title="Budgets & Forecasts" description="Plan by account and department, then compare with posted actuals"><template #actions><ZButton @click="showToast('Budget draft saved','Backend approval will be required before this becomes authoritative.','info')">Save draft</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Annual budget" :value="formatMoney(budget)" tone="brand"/><StatCard label="Actual spend" :value="formatMoney(actual)"/><StatCard label="Available" :value="formatMoney(budget-actual)" :tone="budget>=actual?'success':'danger'"/><StatCard label="AI forecast" :value="formatMoney(forecast)" tone="warning" hint="Preview estimate · not posted"/></div><Panel><Toolbar><select v-model="year" class="field w-36"><option>FY 2026</option><option>FY 2027 draft</option></select><select v-model="department" class="field w-48"><option>All departments</option><option>Engineering</option><option>Sales</option><option>Operations</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1100"><template #account="{row}"><span class="font-medium text-content">{{row.account}}</span></template><template #department="{row}">{{row.department}}</template><template #category="{row}">{{row.category}}</template><template #month="{row}">{{row.month}}</template><template #budget="{row}">{{formatMoney(row.budget)}}</template><template #actual="{row}">{{formatMoney(row.actual)}}</template><template #variance="{row}"><span :class="row.variance>=0?'text-success':'text-danger'">{{formatMoney(row.variance)}}</span></template><template #forecast="{row}">{{formatMoney(row.forecast)}}</template><template #status="{row}"><StatusBadge :status="row.status" :label="row.status==='over_budget'?'Over budget':'On track'"/></template></DataTable></Panel></AppShell></template>